// extract-artifacts.mjs
// Reads compiled Hardhat artifacts from /tmp/farflappy (or FARFLAPPY_CONTRACTS_DIR)
// and generates js/contracts-data.js with ABI + creation bytecode for the
// three FarFlappy AI Arena contracts.
//
// DO NOT hand-write bytecode. Re-run this script whenever the .sol files
// change and Hardhat has been re-compiled, then verify the output:
//   node scripts/extract-artifacts.mjs
//   node scripts/extract-artifacts.mjs --verify
//
// The generated file contains ONLY public ABI + bytecode. No private keys,
// no addresses of real deployments, no secrets of any kind.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = dirname(here); // /tmp/flap-deploy
const farflappyDir = process.env.FARFLAPPY_CONTRACTS_DIR
  || '/tmp/farflappy/contracts';
const artifactsDir = join(farflappyDir, 'artifacts', 'src');
const outPath = join(repoRoot, 'js', 'contracts-data.js');

const CONTRACTS = ['FlapPilot', 'FlapToken', 'FlapArena'];

function sha256Hex(s) {
  return createHash('sha256').update(s).digest('hex');
}

function load(name) {
  const p = join(artifactsDir, `${name}.sol`, `${name}.json`);
  const data = JSON.parse(readFileSync(p, 'utf8'));
  if (!data.abi || !data.bytecode) {
    throw new Error(`${name}: artifact at ${p} is missing abi or bytecode`);
  }
  return {
    abi: data.abi,
    bytecode: data.bytecode,
    bytecodeSha256: sha256Hex(data.bytecode),
    bytecodeLength: data.bytecode.length,
    source: `contracts/src/${name}.sol`,
    artifact: `artifacts/src/${name}.sol/${name}.json`,
  };
}

const contracts = {};
for (const name of CONTRACTS) contracts[name] = load(name);

mkdirSync(join(repoRoot, 'js'), { recursive: true });
const header = `// AUTO-GENERATED by scripts/extract-artifacts.mjs — DO NOT EDIT BY HAND.\n`
  + `// Source: Hardhat artifacts from ${farflappyDir}\n`
  + `// Re-generate after any .sol change: node scripts/extract-artifacts.mjs\n`
  + `// This file contains only public ABI + creation bytecode. No private keys.\n`;
const body = `window.FLAP_CONTRACTS = ${JSON.stringify(contracts, null, 2)};\n`;
writeFileSync(outPath, header + body, 'utf8');
console.log(`Wrote ${outPath}`);
for (const name of CONTRACTS) {
  console.log(`  ${name}: bytecode length=${contracts[name].bytecodeLength} sha256=${contracts[name].bytecodeSha256} prefix=${contracts[name].bytecode.slice(0, 20)}`);
}

if (process.argv.includes('--verify')) {
  // Re-read the generated file in a sandbox and compare byte-for-byte.
  const generated = readFileSync(outPath, 'utf8');
  const match = generated.match(/window\.FLAP_CONTRACTS = (\{[\s\S]*\});\s*$/);
  if (!match) throw new Error('generated file could not be parsed for verification');
  const parsed = JSON.parse(match[1]);
  let ok = true;
  for (const name of CONTRACTS) {
    const orig = load(name);
    const same = parsed[name].bytecode === orig.bytecode
      && parsed[name].bytecodeSha256 === orig.bytecodeSha256
      && JSON.stringify(parsed[name].abi) === JSON.stringify(orig.abi);
    console.log(`  verify ${name}: ${same ? 'OK (bytecode identical, sha256 matches)' : 'MISMATCH'}`);
    if (!same) ok = false;
  }
  if (!ok) { console.error('VERIFICATION FAILED'); process.exit(1); }
  console.log('VERIFICATION OK: generated bytecode is identical to Hardhat artifacts.');
}
